const input = $node["AI Agent"].json.output || [];
const validDepartments = [
  "headTable", "technical", "prHr", "design", "rAndD", "contentAndMedia",
  "marketing", "logisticsAndOperations", "communication", "videography",
  "innovation", "sponsorship", "creativity", "offstage"
];
const validDesignations = ["lead", "colead", "associate", "president", "vicePresident", "secretary"];

const departmentMap = {
  "tech": "technical",
  "pr": "prHr",
  "hr": "prHr",
  "rnd": "rAndD",
  "content": "contentAndMedia",
  "media": "contentAndMedia",
  "logistics": "logisticsAndOperations",
  "operations": "logisticsAndOperations",
  "video": "videography"
};

const results = [];

// Handle both single object and array inputs
const inputArray = Array.isArray(input) ? input : [input];

for (let item of inputArray) {
  let department = item.department ? item.department.toLowerCase() : "";
  let designation = item.designation ? item.designation.toLowerCase() : "";

  // If only designation is provided and it's a headTable-specific designation
  if (!department && ["president", "vicepresident", "secretary"].includes(designation)) {
    department = "headTable";
  }

  // Normalize department
  department = departmentMap[department] || department;

  // Validate and add to results if both are valid
  if (validDepartments.includes(department) && validDesignations.includes(designation)) {
    results.push({ department, designation });
  }
}

return [{ json: { queries: results } }];

const raw = $input.first().json.output;

// Remove code block formatting
const cleaned = raw
  .replace(/^```json\n/, '')
  .replace(/\n```$/, '');

// Parse to JSON
const parsed = JSON.parse(cleaned);

// Ensure it's always an array
const queries = Array.isArray(parsed) ? parsed : [parsed];

const items = queries.map(query => ({
  json: query
}));

return items;
